@js:
var full={layout_flexGrow:1,layout_flexBasisPercent:1};
var half={layout_flexGrow:1,layout_flexBasisPercent:0.48};
/* beta4.1：排序页双列专用。0.40 为按钮外边距/圆角留足空间，确保同一源 ↑↓ 稳定同行。 */
var orderHalf={layout_flexGrow:1,layout_flexBasisPercent:0.40};
function saved(k,d){
  try{var m=source.getLoginInfoMap?source.getLoginInfoMap():null;var v=m&&(m.get?m.get(k):m[k]);if(v!==null&&v!==undefined&&String(v)!=='')return String(v);}catch(e0){}
  try{var j=JSON.parse(String(source.getLoginInfo()||'{}'))||{};if(j[k]!==undefined&&j[k]!==null&&String(j[k])!=='')return String(j[k]);}catch(e1){}
  return d==null?'':String(d);
}
function pbtn(name,action,style){return{name:name,type:'button',action:action,style:style||full};}
/* beta2：设置页只维护“有哪些源”，排序不再枚举排列组合。未来新增源只需追加到对应数组。 */
var QF_UI_PROVIDER_V310={
  '限免源':['情无','神魔','晴天','同人'],
  '优选源':['七猫','书旗','QQ浏览器','得间','酷我'],
  '兜底源':['猫眼','得奇','69书吧','速读谷','万相']
};
function qfUiTierNamesV310(){var a=[];for(var k in QF_UI_PROVIDER_V310)if(Object.prototype.hasOwnProperty.call(QF_UI_PROVIDER_V310,k))a.push(k);return a;}
function qfUiOrderV310(key,allow){
  allow=allow||[];var raw=saved(key,allow.join('→')),a=String(raw||'').split(/[→>＞]/),out=[];
  for(var i=0;i<a.length;i++){var x=String(a[i]||'').trim();if(allow.indexOf(x)>=0&&out.indexOf(x)<0)out.push(x);}
  for(var j=0;j<allow.length;j++)if(out.indexOf(allow[j])<0)out.push(allow[j]);
  return out;
}
function qfUiOrderPageV310(group,allow,key,title){
  allow=allow||[];var order=qfUiOrderV310(key,allow),enc=encodeURIComponent(JSON.stringify(allow));
  /* 页头也按双列收紧；源较多时尽量把纵向空间留给排序项。 */
  ui.push(pbtn('‹  返回','qfBackUiPageV30()',orderHalf));
  ui.push(pbtn(title+' · '+order.join(' → '),'qfLoginHelpV307()',orderHalf));
  for(var i=0;i<order.length;i++){
    var n=order[i],pos=(i+1)+'/'+order.length;
    /* 同一个源固定占一行：左 ↑，右 ↓。 */
    ui.push(pbtn('↑  '+pos+'  '+n,"qfOrderMoveV310("+JSON.stringify(group)+","+JSON.stringify(n)+",-1,'"+enc+"')",orderHalf));
    ui.push(pbtn(pos+'  '+n+'  ↓',"qfOrderMoveV310("+JSON.stringify(group)+","+JSON.stringify(n)+",1,'"+enc+"')",orderHalf));
  }
  ui.push(pbtn('↺  恢复默认顺序',"qfOrderResetV310("+JSON.stringify(group)+",'"+enc+"')",full));
  ui.push(pbtn('每个源只占一行：左侧上移、右侧下移。新加入的正文源若旧排序不存在，会自动追加到本类别末尾。','qfLoginHelpV307()',full));
}
var page='main';try{page=String(source.get('qf_ui_page')||'main');}catch(e0){}
var ui=[];
var qwBase=saved('情无接口地址','http://103.236.85.8:7878/qd');try{qwBase=String(source.get('qf_qw_base')||qwBase);}catch(e1){}
/* beta17：情无会话独立镜像优先；旧 loginHeader/loginInfo 仅作兼容回退。 */
var qwAuth={},qwHead={};
try{qwAuth=JSON.parse(String(source.getLoginInfo()||'{}'))||{};}catch(e2){qwAuth={};}
try{qwHead=JSON.parse(String(source.getLoginHeader()||'{}'))||{};}catch(e3){qwHead={};}
var qwBridgeToken=saved('情无会话令牌','');var qwToken='';try{qwToken=String(source.get('qf_qw_token_v317')||qwBridgeToken||qwAuth.request_token||qwHead['X-Content-Token']||'');}catch(_qt){qwToken=String(qwBridgeToken||qwAuth.request_token||qwHead['X-Content-Token']||'');}
var qwBridgeCookie=saved('情无会话Cookie','');var qwCookie='';try{qwCookie=String(source.get('qf_qw_cookie_v317')||qwBridgeCookie||qwHead.Cookie||'');}catch(_qc){qwCookie=String(qwBridgeCookie||qwHead.Cookie||'');}
var qwKeys=-1;try{var _qk=source.get('qf_qw_keys_v317');if(_qk===null||_qk===undefined||String(_qk)==='')_qk=saved('情无共享凭据','');if(_qk!==null&&_qk!==undefined&&String(_qk)!=='')qwKeys=Number(_qk);}catch(_qke){var _qkb=saved('情无共享凭据','');if(_qkb)qwKeys=Number(_qkb);}
var qwReady=!!qwToken;
var qwVerified=qwReady&&qwKeys>=0;
var qwWebOnly=!qwReady&&!!qwCookie;
var smReady=false,smBase='https://shenmobook.top';
var qtReady=false,qtBase='https://sb.shazi.tk';
var trReady=false,trTokenLen=0;
try{
    var _trv=String(source.getVariable?source.getVariable():'').trim(),_tro=null;
    if(_trv&&_trv.charAt(0)==='{'){
        try{_tro=JSON.parse(_trv);}catch(_trp){_tro=null;}
        if(_tro&&typeof _tro==='object'&&Object.prototype.hasOwnProperty.call(_tro,'qfV21Search'))_trv='';
    }
    trReady=!!_trv;trTokenLen=_trv.length;
}catch(eTr){}
try{smReady=String(source.get('qf_sm_logged')||'')==='1';}catch(e4){}
try{smBase=String(source.get('qf_sm_base')||smBase);}catch(e5){}
try{qtReady=String(source.get('qf_qt_logged')||'')==='1'||(String(source.get('qf_qt_key')||'')&&String(source.get('qf_qt_dttoken')||''));}catch(e51){}
try{qtBase=String(source.get('qf_qt_base')||qtBase);}catch(e52){}

/* alpha7：三类正文源严格隔离。旧设置只用于首次迁移默认值。 */
var tierHint='';try{tierHint=String(source.get('qf_ui_tier_v308')||'');}catch(_th){}
var tier=(tierHint==='限免源'||tierHint==='优选源'||tierHint==='兜底源'||tierHint==='STV源'||tierHint==='全源智能')?tierHint:saved('正文源类别','');
if(tier!=='限免源'&&tier!=='优选源'&&tier!=='兜底源'&&tier!=='STV源'&&tier!=='全源智能'){
  tier=saved('是否选择限免源','否')==='是'?'限免源':'优选源';
}
var limitedAllow=QF_UI_PROVIDER_V310['限免源']||[],preferredAllow=QF_UI_PROVIDER_V310['优选源']||[],fallbackAllow=QF_UI_PROVIDER_V310['兜底源']||[];
var stvAllow=['STV·自动','STV·qidian'];
var stvPick=saved('STV源选择','STV·自动');if(stvAllow.indexOf(stvPick)<0)stvPick='STV·自动';
var stvKey=saved('STV API密钥','');
var limitedPick=saved('限免源选择','自动');if(['自动'].concat(limitedAllow).indexOf(limitedPick)<0)limitedPick='自动';
var preferredPick=saved('优选源选择','');
if(['自动'].concat(preferredAllow).indexOf(preferredPick)<0){
  var oldPick=saved('付费正文来源','自动');preferredPick=preferredAllow.indexOf(oldPick)>=0?oldPick:'自动';
}
var fallbackPick=saved('兜底源选择','自动');if(['自动'].concat(fallbackAllow).indexOf(fallbackPick)<0)fallbackPick='自动';
var activeKey=tier==='全源智能'?'全源智能选择':(tier==='STV源'?'STV源选择':(tier==='限免源'?'限免源选择':(tier==='兜底源'?'兜底源选择':'优选源选择')));
var activeAllow=tier==='STV源'?stvAllow:(tier==='限免源'?limitedAllow:(tier==='兜底源'?fallbackAllow:(tier==='优选源'?preferredAllow:[])));
var activeChars=tier==='全源智能'?['自动']:['自动'].concat(activeAllow);
var activeDefault=tier==='全源智能'?'自动':(tier==='STV源'?stvPick:(tier==='限免源'?limitedPick:(tier==='兜底源'?fallbackPick:preferredPick)));
var experienceMode='自定义';try{experienceMode=String(QF_SettingsProfile.current(this)||'自定义');}catch(_ep){var _x=saved('体验模式','');experienceMode=['极速','均衡','完整','自定义'].indexOf(_x)>=0?_x:'自定义';}

if(page==='profile'){
  ui.push(pbtn('‹  返回','qfBackUiPageV30()',half));
  ui.push(pbtn('🎛  体验模式 · '+experienceMode,'qfLoginHelpV307()',half));
  ui.push({name:'体验模式',viewName:"'体验模式'",type:'select',chars:['极速','均衡','完整','自定义'],default:experienceMode,action:"qfSettingsPresetChange()",style:full});
  ui.push(pbtn('⚡  极速 · 纯正文优先\n关闭段评、热评、本章说、作者说和兜底段评智能对齐，最大限度减少阅读附加请求。','qfSettingsPresetApply("极速")',full));
  ui.push(pbtn('⚖️  均衡 · 推荐日常\n保留段评、本章说、作者说和智能对齐，关闭高开销热评；兼顾互动信息与加载速度。','qfSettingsPresetApply("均衡")',full));
  ui.push(pbtn('🌟  完整 · 功能全开\n开启段评、热评、本章说、作者说和兜底段评智能对齐，优先完整体验。','qfSettingsPresetApply("完整")',full));
  ui.push(pbtn('✏️  自定义 · 保留当前值\n不改现有高级设置；之后手动修改受管开关也会自动进入“自定义”。','qfSettingsPresetApply("自定义")',full));
  ui.push(pbtn('预设只管理评论/附加阅读负载开关，不会修改正文源类别、具体 Provider、Provider 排序、账号、段评服务器、弹窗高度/圆角或开发者诊断。','qfLoginHelpV307()',full));
}
else if(page==='accounts'){
  ui.push(pbtn('‹  返回','qfBackUiPageV30()',half));
  ui.push(pbtn('🔐  限免源账号','qfLoginHelpV307()',half));
  ui.push(pbtn('🌙  情无    '+(qwVerified?'● 会话已验证 · 凭据'+qwKeys:(qwReady?'◐ 令牌已保存':(qwWebOnly?'◐ 仅网页会话':'○ 未登录'))),'qfOpenUiPageV30("qw")',full));
  ui.push(pbtn('⚔️  神魔    '+(smReady?'● 已登录':'○ 未登录'),'qfOpenUiPageV30("sm")',full));
  ui.push(pbtn('☀️  晴天    '+(qtReady?'● 已登录':'○ 未登录'),'qfOpenUiPageV30("qt")',full));
  ui.push(pbtn('🍋  同人    '+(trReady?'● 源变量 Token 已填写':'○ 未设置源变量 Token'),'qfOpenUiPageV30("tr")',full));
  ui.push(pbtn('🌐  STV     '+(stvKey?'● API密钥已填写':'○ API密钥未填写（可选）'),'qfOpenUiPageV30("stv")',full));
}
else if(page==='tr'){
  ui.push(pbtn('‹  返回','qfBackUiPageV30()',half));
  ui.push(pbtn('🍋  同人 · '+(trReady?'Token 已填写':'未设置 Token'),'qfTrHelpV102()',half));
  ui.push(pbtn('✓  检测共享 Token','qfTrCheckV102()',half));
  ui.push(pbtn('🌐  进入同人后台','qfTrOpenConsoleV102()',half));
  ui.push(pbtn('鉴权方式与情无/神魔不同：不填写账号密码。请退出登录设置，在“编辑书源 → 设置源变量”填写共享 Token。Token 只供同人 Provider 使用，不写入登录信息。','qfTrHelpV102()',full));
  ui.push(pbtn('当前状态：'+(trReady?('已填写 · 长度 '+trTokenLen):'未填写'),'qfTrCheckV102()',full));
}
else if(page==='stv'){
  ui.push(pbtn('‹  返回','qfBackUiPageV30()',half));
  ui.push(pbtn('🌐  STV · '+(stvKey?'API密钥已填写':'API密钥未填写'),'qfLoginHelpV307()',half));
  ui.push({name:'STV API密钥',viewName:"'STV API密钥（可选）'",type:'password',default:stvKey,hint:'xianren API Key；没有可先留空',action:"qfLoginSave('STV API密钥')",style:full});
